// contentFactory.js
export const contentFactory = (type, token) => {
  const API_BASE = "http://127.0.0.1:8000/api";

  // Генерація slug
  const generateSlug = (text) => {
    return (
      text
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "") +
      "-" +
      Date.now()
    );
  };

  // Створення статті за категорією
  const fetchArticle = async (data) => {
    const formData = new FormData();
    formData.append("title", data.title);
    formData.append("slug", data.slug || generateSlug(data.title));
    formData.append("content", data.content || "");
    formData.append("excerpt", data.excerpt || "");
    formData.append("category", data.category || "sport");
    formData.append("status", data.status || "draft");
    formData.append("type", "standard");
    formData.append("is_premium", data.is_premium ? "true" : "false");

    if (data.author) formData.append("author", data.author);

    const res = await fetch(`${API_BASE}/articles/`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    if (!res.ok) {
      const errData = await res.json();
      console.error("📛 Помилка створення статті:", errData);
      throw new Error("Не вдалося створити статтю");
    }

    return await res.json();
  };

  // Створення статті для каналу
  const fetchChannelArticle = async (data) => {
    const formData = new FormData();
    formData.append("title", data.title);
    formData.append("slug", data.slug || generateSlug(data.title));
    formData.append("content", data.content || "");
    formData.append("excerpt", data.excerpt || "");
    formData.append("category", data.category || "News");
    formData.append("status", data.status || "published");
    formData.append("type", "channel");
    formData.append("is_premium", data.is_premium ? "true" : "false");

    if (data.channel) formData.append("channel", data.channel);
    if (data.author) formData.append("author", data.author);

    const res = await fetch(`${API_BASE}/articles/`, {
      method: "POST",
      headers: { Authorization: `Bearer ${token}` },
      body: formData,
    });

    if (!res.ok) {
      const errData = await res.json();
      console.error("📛 Помилка створення статті для каналу:", errData);
      throw new Error("Не вдалося створити статтю для каналу");
    }

    return await res.json();
  };

  // Створення опитування
  const fetchPoll = async (data) => {
    const body = {
      question: data.question,
      choices: data.options.map((text) => ({ text })),
      channel: data.channel || null,
    };

    const res = await fetch(`${API_BASE}/polls/`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      const errData = await res.json();
      console.error("📛 Помилка створення опитування:", errData);
      throw new Error("Не вдалося створити опитування");
    }

    return await res.json();
  };

  switch (type) {
    case "article":
      return fetchArticle;
    case "channelArticle":
      return fetchChannelArticle;
    case "poll":
      return fetchPoll;
    default:
      throw new Error("Невідомий тип контенту");
  }
};
